"""Capture an actual maintained gate input, then detach it through host storage."""

from __future__ import annotations

import hashlib
import time
from collections.abc import Callable, Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from typing import TYPE_CHECKING, Protocol, cast

import numpy as np

from wyat.benchmark import BenchmarkCycle, BenchmarkEngine, _run
from wyat.core import Model
from wyat.evaluation import EvaluationCase

if TYPE_CHECKING:
    import mlx.core as mx

    from wyat.backends.kai.mlx import MLXKaiScorer
    from wyat.backends.kai.prefix import PrefixScorer


@dataclass(frozen=True, slots=True)
class CapturedInput:
    values: np.ndarray[tuple[int, int], np.dtype[np.float32]]
    cycle: BenchmarkCycle
    copy_elapsed_ms: float

    def metadata(self) -> dict[str, object]:
        return {
            "copy_materialization_elapsed_ms": self.copy_elapsed_ms,
            "shape": list(self.values.shape),
            "dtype": str(self.values.dtype),
            "host_strides_bytes": list(self.values.strides),
            "sha256": hashlib.sha256(self.values.tobytes()).hexdigest(),
            "nbytes": self.values.nbytes,
        }


class CaptureFailure(ValueError):
    def __init__(self, message: str, cycle: BenchmarkCycle) -> None:
        super().__init__(message)
        self.cycle = cycle


class CaptureProjection:
    """Call the unchanged projection and observe its exact argument once."""

    def __init__(self, original: Callable[[mx.array], mx.array]) -> None:
        self.original = original
        self.inputs: list[mx.array] = []

    def __call__(self, value: mx.array) -> mx.array:
        self.inputs.append(value)
        return self.original(value)


class ProjectionOwner(Protocol):
    gate_proj: Callable[[mx.array], mx.array]


@contextmanager
def observe_projection(owner: ProjectionOwner) -> Iterator[CaptureProjection]:
    original = owner.gate_proj
    observer = CaptureProjection(original)
    owner.gate_proj = observer
    try:
        yield observer
    finally:
        owner.gate_proj = original


def detached_float32(
    value: mx.array,
) -> np.ndarray[tuple[int, int], np.dtype[np.float32]]:
    """A host-owned copy cannot retain a lazy model graph or checkpoint owner."""
    import mlx.core as mx

    if value.dtype != mx.float32 or len(value.shape) not in (2, 3):
        raise ValueError("Capture requires a rank2/3 FP32 activation")
    mx.eval(value)
    host = np.array(value, dtype=np.float32, copy=True).reshape(-1, value.shape[-1])
    if not np.isfinite(host).all():
        raise ValueError("Actual capture contains nonfinite activations")
    return np.ascontiguousarray(host)


def capture_input(
    base: MLXKaiScorer,
    scorer: MLXKaiScorer | PrefixScorer,
    cases: tuple[EvaluationCase, ...],
    *,
    batch_size: int,
    expected_rows: int,
) -> CapturedInput:
    """One declared batch only; prefix construction must precede this hook."""
    if not cases or len(cases) != batch_size:
        raise ValueError("Capture requires one complete declared batch")
    with observe_projection(
        cast(ProjectionOwner, base.backbone.layers[0].mlp)
    ) as observer:
        cycle = _run(
            BenchmarkEngine(
                "actual-activation-capture", Model(scorer, base.model_id), batch_size
            ),
            cases,
        )
        if cycle.failed or len(observer.inputs) != 1:
            raise CaptureFailure(
                "Capture did not visit exactly one successful gate call", cycle
            )
        started = time.perf_counter_ns()
        values = detached_float32(observer.inputs[0])
        copy_elapsed_ms = (time.perf_counter_ns() - started) / 1e6
        if values.shape != (expected_rows, 1024):
            raise CaptureFailure(
                "Actual projection input differs from declared geometry", cycle
            )
    return CapturedInput(values, cycle, copy_elapsed_ms)


def exact_bfloat_bits(
    values: np.ndarray[tuple[int, int], np.dtype[np.float32]],
) -> bool:
    """BF16 decode preserves FP32 bits, including the sign of zero."""
    return bool(
        np.isfinite(values).all() and np.all((values.view(np.uint32) & 0xFFFF) == 0)
    )


def projection_quality(
    reference: np.ndarray[tuple[int, int], np.dtype[np.float32]],
    candidate: np.ndarray[tuple[int, int], np.dtype[np.float32]],
) -> dict[str, object]:
    if (
        reference.shape != candidate.shape
        or reference.dtype != candidate.dtype
        or reference.dtype != np.float32
    ):
        raise ValueError("Projection quality requires matching FP32 shapes")
    finite = bool(np.isfinite(reference).all() and np.isfinite(candidate).all())
    difference = np.abs(candidate.astype(np.float64) - reference.astype(np.float64))
    failures = (~np.isfinite(difference)) | (
        difference > 1e-4 + 1e-4 * np.abs(reference.astype(np.float64))
    )
    return {
        "passed": finite and not bool(failures.any()),
        "finite": finite,
        "failing_elements": int(failures.sum()),
        "total_elements": reference.size,
        "max_abs_error": float(difference.max()) if finite else None,
        "atol": 1e-4,
        "rtol": 1e-4,
    }

"""One fixed tile policy: float SIMD arithmetic with independent weight storage.

Preparation checks actual device strides without asking MLX to copy inputs.
Only the public custom Metal API and Metal SIMD matrix operations are used.
This experiment does not replace production matmul.
"""

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Protocol, cast

import mlx.core as mx

TILE = 32
THREADS = 128
SHARED_BYTES = 3 * TILE * TILE * 4
HEADER = """
#include <metal_simdgroup>
#include <metal_simdgroup_matrix>
"""
SOURCE = """
const uint M = X_shape[0];
const uint K = X_shape[1];
const uint N = W_shape[0];
const uint tid = thread_index_in_threadgroup;
const uint group = simdgroup_index_in_threadgroup;
const uint row_start = threadgroup_position_in_grid.y * 32;
const uint col_start = threadgroup_position_in_grid.x * 32;
const uint group_row = (group / 2) * 16;
const uint group_col = (group % 2) * 16;

threadgroup float x_tile[1024];
threadgroup float w_tile[1024];
threadgroup float output_tile[1024];
simdgroup_float8x8 accumulators[4];
for (uint i = 0; i < 4; ++i) {
    accumulators[i] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
}

for (uint start = 0; start < K; start += 32) {
    for (uint i = tid; i < 1024; i += 128) {
        const uint local_row = i / 32;
        const uint local_col = i % 32;
        const uint row = row_start + local_row;
        const uint col = col_start + local_row;
        const uint reduction = start + local_col;
        x_tile[i] = (row < M && reduction < K)
            ? float(X[size_t(row) * K + reduction]) : 0.0f;
        // Stage W.T in float; no complete FP32 weight allocation.
        w_tile[local_col * 32 + local_row] = (col < N && reduction < K)
            ? float(W[size_t(col) * K + reduction]) : 0.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint reduction = 0; reduction < 32; reduction += 8) {
        simdgroup_float8x8 a[2];
        simdgroup_float8x8 b[2];
        for (uint i = 0; i < 2; ++i) {
            simdgroup_load(a[i], x_tile + (group_row + i * 8) * 32
                + reduction, 32);
            simdgroup_load(b[i], w_tile + reduction * 32
                + group_col + i * 8, 32);
        }
        for (uint row = 0; row < 2; ++row) {
            for (uint col = 0; col < 2; ++col) {
                const uint i = row * 2 + col;
                simdgroup_multiply_accumulate(accumulators[i], a[row], b[col],
                    accumulators[i]);
            }
        }
    }
    // No thread overwrites staged operands before every SIMD group finishes.
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

for (uint row = 0; row < 2; ++row) {
    for (uint col = 0; col < 2; ++col) {
        simdgroup_store(accumulators[row * 2 + col], output_tile
            + (group_row + row * 8) * 32 + group_col + col * 8, 32);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint i = tid; i < 1024; i += 128) {
    const uint row = row_start + i / 32;
    const uint col = col_start + i % 32;
    if (row < M && col < N) {
        Y[size_t(row) * N + col] = output_tile[i];
    }
}
"""

LAYOUT_SOURCE = """
if (thread_position_in_grid.x == 0) {
    layout[0] = X_strides[0];
    layout[1] = X_strides[1];
    layout[2] = W_strides[0];
    layout[3] = W_strides[1];
}
"""


class MetalKernel(Protocol):
    def __call__(
        self,
        *,
        inputs: Sequence[mx.array],
        grid: tuple[int, int, int],
        threadgroup: tuple[int, int, int],
        output_shapes: Sequence[tuple[int, ...]],
        output_dtypes: Sequence[mx.Dtype],
    ) -> list[mx.array]: ...


@dataclass(frozen=True)
class PreparedProjection:
    """Validated inputs held ready; run excludes preparation and layout dispatch."""

    x: mx.array
    weight: mx.array
    kernel: MetalKernel

    def run(self) -> mx.array:
        rows, _ = self.x.shape
        columns, _ = self.weight.shape
        return self.kernel(
            inputs=[self.x, self.weight],
            grid=(
                THREADS * ((columns + TILE - 1) // TILE),
                (rows + TILE - 1) // TILE,
                1,
            ),
            threadgroup=(THREADS, 1, 1),
            output_shapes=[(rows, columns)],
            output_dtypes=[mx.float32],
        )[0]


class ProjectionKernel:
    """Build once; MLX compiles specializations lazily on evaluated dispatch."""

    def __init__(self) -> None:
        self._projection = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_mixed_projection",
                input_names=["X", "W"],
                output_names=["Y"],
                source=SOURCE,
                header=HEADER,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )
        self._layout = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_mixed_layout",
                input_names=["X", "W"],
                output_names=["layout"],
                source=LAYOUT_SOURCE,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )

    def prepare(self, x: mx.array, weight: mx.array) -> PreparedProjection:
        if x.dtype != mx.float32 or weight.dtype not in (mx.float32, mx.bfloat16):
            raise ValueError("Projection requires FP32 X and FP32 or BF16 W")
        if x.ndim != 2 or weight.ndim != 2:
            raise ValueError("Projection requires rank-two X[M,K] and W[N,K]")
        if any(d <= 0 or d > 2**31 - 1 for d in (*x.shape, *weight.shape)):
            raise ValueError("Projection dimensions must be positive int32 values")
        if x.shape[1] != weight.shape[1]:
            raise ValueError("Projection reduction dimensions differ")
        layout = self._layout(
            inputs=[x, weight],
            grid=(1, 1, 1),
            threadgroup=(1, 1, 1),
            output_shapes=[(4,)],
            output_dtypes=[mx.int64],
        )[0]
        mx.eval(layout)
        observed = cast(list[int], layout.tolist())
        expected = [x.shape[1], 1, weight.shape[1], 1]
        if observed != expected:
            raise ValueError(f"Projection requires row-contiguous inputs: {observed}")
        return PreparedProjection(x, weight, self._projection)

